body_md:
\label{thm:main-02}
		 Let $K\in C^\infty(M)$ be a positive function,	$h\equiv 0$, $
		\rho=2\pi$, $ \rho'=0.	$
Suppose that $p\in\partial M$
		is a maximum point of
		$$
		A+2\log K
		\qquad\text{on }\partial M.
		$$
		If
		\begin{equation}
			\begin{aligned}
				&\frac{K_\nu(p)}{K(p)}+2\kappa(p)<0,				
			\end{aligned}
		\end{equation}
		then $J_{2\pi,0}$ attains its minimizer in $W^{1,2}(M)$.
		Consequently, the following equation
\begin{equation}\label{equation:17}
		\begin{cases}
			\displaystyle
			-\Delta_g u+\frac{4\pi}{|M|}
			=2 Ke^u,
			& \text{in }M,\\
			\partial_\nu u
			=0,
			& \text{on }\partial M.
		\end{cases}
	\end{equation}
 admits a smooth solution.

\label{cor:01}
Let $K$ be a smooth positive function on $\mathbb S^2_+$, $h\geq 0$ be a constant. Suppose that $p\in\partial \mathbb S^2_+$ is a maximum point of		$K$ on $\partial \mathbb S^2_+$, i.e. $K(p)=\max_{\partial \mathbb S^2_+}K(x)$. If	$$	\partial_{\nu}K(p)<0,$$ then the prescribed curvature problem
\eqref{equation:15}
admits a smooth solution.

\label{prop:lower-bound}
If $\{u_\epsilon\}$ blows up, then we have the following energy bound \begin{align*}
\liminf_{\epsilon\to 0}J_{\rho_\epsilon,
			\rho'}(u_\epsilon)\geq& -4\pi+2\rho'+ 4\pi\log 4-2(2\pi+\rho')\log(2\pi+\rho')\notag\\&-2\pi \max_{p\in \partial M}\left(A(p) +\frac{\rho}{\pi}\log K(p)+\frac{\rho'}{\pi}\log h^2(p)\right).\end{align*}

If not, we may assume  $$\lim_{\epsilon\to 0}\frac{dist(x_\epsilon,\ \partial^0D^+)}{\delta_\epsilon}=+\infty.$$ Then $$\{x\in\mathbb R^2\ |\ x_\epsilon+\delta_\epsilon x\in D^+\}\to \mathbb R^2,\ \ as\ \ \epsilon\searrow 0.$$
Since $w_\epsilon(x)\leq w_\epsilon (0)=0$, the standard estimates for the Liouville type equation yield $\|w_\epsilon\|_{C^3(D_R)}\leq C$. Passing to a subsequence, we may assume that $$w_\epsilon\rightharpoonup w\ \ in\ \ C^{2}_{loc}(\mathbb R^2),$$ where $w$ satisfies
	\begin{align*}
		-\Delta w= 2\rho K(p)e^{w}\ \ in \ \ \mathbb R^2.
	\end{align*}
The classification result in \cite{Chen-Li} gives that $$w(x)=-2\log(1+\frac{2\rho K(p)}{8}|x|^2).$$
Thus we have
\begin{align*}
2\rho=\lim_{\epsilon\to 0}2\rho_\epsilon\int_M Ke^{v_\epsilon}dv_g\geq \int_{\mathbb R^2}2\rho K(p)e^{w}dx=8\pi
\end{align*} which yields $\rho\geq 4\pi$. This is a contradiction to $\rho\leq 2\pi$.

\label{lem:02}
		Let
		$
		G_\epsilon(x):=G(x,x_\epsilon).
		$
		In $M \backslash B_{R\delta_\epsilon}(x_\epsilon)$, we have
		\begin{equation}
			\left.
			\begin{aligned}[b]
				v_\epsilon \geq{}&
				G_\epsilon
				+2\log\delta_\epsilon
				+\log\frac{8\lambda^2}{\widetilde{K}(0)}
				+2\log\frac{R^2}
				{\lambda^2+\left(R-\frac{c\lambda}{\sqrt{2}}\right)^2}
				-A(p)
				+o_\epsilon(1).
			\end{aligned}
			\right.
		\end{equation}

In $M \backslash B_{R\delta_\epsilon}(x_\epsilon)$,
		\begin{equation*}
			\left.
			\begin{aligned}
				\Delta(v_\epsilon-G_\epsilon)
				={}&
				\frac{2(\rho+\rho'-\epsilon)}{|M|}
				-2(\rho-\epsilon)K e^{v_\epsilon}
				-\frac{4\pi}{|M|} \\
				={}&
				-\frac{2\epsilon}{|M|}
				-2(\rho-\epsilon)K e^{v_\epsilon}
				\leq 0.
			\end{aligned}
			\right.
		\end{equation*}

		Since $x_\epsilon\to p$ and the regular part $A$ of the Green
		function is continuous on $\partial M$ (c.f. \cite{Hu-Bartsch} Lemma 2.1), we have
		$
		A(x_\epsilon)=A(p)+o_\epsilon(1).
		$
		Therefore,
		\begin{equation*}
			\left.
			\begin{aligned}
				(v_\epsilon-G_\epsilon)
				\big|_{\partial B_{R\delta_\epsilon}(x_\epsilon)}
=&-2\log\delta_\epsilon
				+w\big|_{\partial^+B_R(0)}
				+4\log(R\delta_\epsilon)
				-A(x_\epsilon)+o_{\epsilon}(1)
				 \\
				=&
				-2\log\delta_\epsilon
				+w\big|_{\partial^+B_R(0)}
				+4\log(R\delta_\epsilon)
				-A(p)
				+o_{\epsilon}(1) \\
				\geq &
				2\log\delta_\epsilon
				+\log\frac{8\lambda^2}{\widetilde{K}(0)}
				+2\log\frac{R^2}
				{\lambda^2+\left(R-\frac{c\lambda}{\sqrt{2}}\right)^2}
				-A(p)
				+o_\epsilon(1).
			\end{aligned}
			\right.
		\end{equation*}
		Moreover,
		\[
		\frac{\partial(v_\epsilon-G_\epsilon)}{\partial\nu}
		\bigg|_{\partial M\setminus B_{R\delta_\epsilon}(x_\epsilon)}
		=
		\frac{\partial v_\epsilon}{\partial\nu}
		\bigg|_{\partial M\setminus B_{R\delta_\epsilon}(x_\epsilon)}
		\geq 0.
		\]
		Applying the strong maximum principle, we get the conclusion of the
		lemma.

\label{lem:01}
		There holds
		\begin{align*}
			\lim\limits_{R\rightarrow +\infty}\lim\limits_{\epsilon\rightarrow 0}\int_{M \backslash B_{R\delta_\epsilon}(x_\epsilon)}\rho_\epsilon K e^{v_\epsilon}dv_g
			+\lim\limits_{R\rightarrow +\infty}\lim\limits_{\epsilon\rightarrow 0}\int_{ \partial M \backslash B_{R\delta_\epsilon}(x_\epsilon)}\rho'  \tilde{h}_\epsilon e^{\frac{v_\epsilon}{2}}ds_g=0.
		\end{align*}

On  one hand, we have
		\begin{align*}
			\lim\limits_{R\rightarrow +\infty}\lim\limits_{\epsilon\rightarrow 0}\left(\int_{ B_{R\delta_\epsilon}(x_\epsilon)}2\rho_\epsilon K e^{v_\epsilon}
			+\int_{ \partial M \cap B_{R\delta_\epsilon}(x_\epsilon)}2\rho'  \tilde{h}_\epsilon e^{\frac{v_\epsilon}{2}}\right)= \int_{\mathbb R^2_+}\tilde{K}(0)e^wdx+ \int_{\partial\mathbb R^2_+}\tilde{h}(0)e^{\frac{w}{2}}=4\pi.
		\end{align*}

		On the other hand,
		\begin{align*}
			\lim\limits_{\epsilon\rightarrow 0}\left(\int_{M}2\rho_\epsilon K e^{v_\epsilon}dv_g
			+\int_{ \partial M }2\rho' \tilde{h}_\epsilon e^{\frac{v_\epsilon}{2}}ds_g\right)=\lim_{\epsilon\to 0}2(\rho_\epsilon+\rho')=4\pi,
		\end{align*} which immediately implies the conclusion of the lemma.

On one hand, it is easy to see that
	\begin{equation}
		\left.
		\begin{aligned}[b]
			\int_{ B_{R\delta_\epsilon}(x_\epsilon)}|\nabla v_\epsilon|^2&=\int_{ B_{R}^+(0)}|\nabla w|^2+o_\epsilon(1)\\
			&=8\pi \log(\lambda^2+R^2) -8\pi\log\lambda^2-8\pi-8\pi\log\frac{2\pi+\rho'}{2\pi-\rho'}+4\rho'+o_R(1)+o_\epsilon(1).
		\end{aligned}
		\right.
	\end{equation}

On the other hand, from the divergence theorem and equation, we have
	\begin{equation}
		\left.
		\begin{aligned}[b]
			\int_{M \backslash B_{R\delta_\epsilon}(x_\epsilon)}|\nabla  v_\epsilon|^2
			=&\int_{M \backslash B_{R\delta_\epsilon}(x_\epsilon)}-v_\epsilon\Delta   v_\epsilon+\int_{ \partial (M \backslash B_{R\delta_\epsilon}(x_\epsilon))}v_\epsilon \frac { \partial v_\epsilon}{\partial \nu}\\
			=&-\frac{2(\rho+\rho'-\epsilon)}{|M|} \int_{M \backslash B_{R\delta_\epsilon}(x_\epsilon)}v_\epsilon+2(\rho-\epsilon)\int_{M \backslash B_{R\delta_\epsilon}(x_\epsilon)} K e^{v_\epsilon} v_\epsilon\\
			&-\int_{ \partial^+ B_{R\delta_\epsilon}(x_\epsilon)}v_\epsilon \frac { \partial v_\epsilon}{\partial r} +2\rho'\int_{ \partial M \backslash B_{R\delta_\epsilon}(x_\epsilon)}  \tilde{h}_\epsilon e^{\frac{v_\epsilon}{2}}v_\epsilon.
		\end{aligned}
		\right.
	\end{equation}

	By Lemma \ref{lem:02} and Lemma \ref{lem:01}, we have
	\begin{align*}
		&2\rho_\epsilon\int_{M \setminus B_{R\delta_\epsilon}(x_\epsilon)} K e^{v_\epsilon} v_\epsilon+2\rho'\int_{ \partial M \setminus B_{R\delta_\epsilon}(x_\epsilon)}  \tilde{h}_\epsilon e^{\frac{v_\epsilon}{2}}v_\epsilon\\
		\geq&2\rho_\epsilon\int_{M \setminus B_{R\delta_\epsilon}(x_\epsilon)} K e^{v_\epsilon}G_\epsilon+4\rho_\epsilon\log\delta_\epsilon\int_{M \setminus B_{R\delta_\epsilon}(x_\epsilon)}K e^{v_\epsilon}\\
		&+2\rho_\epsilon\int_{M \setminus B_{R\delta_\epsilon}(x_\epsilon)} K e^{v_\epsilon}\left(\log\frac{8\lambda^2}{\tilde{K}(0)}+2\log\frac{R^2}{\lambda^2+(R-\frac{c\lambda}{\sqrt{2}})^2}- A(p)  + o_\epsilon(1)+o_R(1)\right)\\
		&+2\rho'\int_{ \partial M \setminus B_{R\delta_\epsilon}(x_\epsilon)} \tilde{h}_\epsilon e^{\frac{v_\epsilon}{2}} G_\epsilon+4\rho' \log\delta_\epsilon\int_{ \partial M \setminus B_{R\delta_\epsilon}(x_\epsilon)}  \tilde{h}_\epsilon e^{\frac{v_\epsilon}{2}}\\
		&+2\rho'\int_{ \partial M \setminus B_{R\delta_\epsilon}(x_\epsilon)}  \tilde{h}_\epsilon e^{\frac{v_\epsilon}{2}}\left(\log\frac{8\lambda^2}{\tilde{K}(0)}+2\log\frac{R^2}{\lambda^2+(R-\frac{c\lambda}{\sqrt{2}})^2}- A(p)  + o_\epsilon(1)+o_R(1)\right)\\
		\geq&2\rho_\epsilon\int_{M \setminus B_{R\delta_\epsilon}(x_\epsilon)} K e^{v_\epsilon}G_\epsilon+4\rho_\epsilon \log\delta_\epsilon\int_{M \setminus B_{R\delta_\epsilon}(x_\epsilon)} K e^{v_\epsilon}\\
		&+2\rho'\int_{ \partial M \setminus B_{R\delta_\epsilon}(x_\epsilon)}  \tilde{h}_\epsilon e^{\frac{v_\epsilon}{2}} G_\epsilon+4\rho' \log\delta_\epsilon\int_{ \partial M \setminus B_{R\delta_\epsilon}(x_\epsilon)} \tilde{h}_\epsilon e^{\frac{v_\epsilon}{2}}+ o_\epsilon(1)+o_R(1).
	\end{align*}

	By the equation and  divergence theorem, we have
	\begin{align*}
		&2\rho_\epsilon\int_{M \setminus B_{R\delta_\epsilon}(x_\epsilon)} K e^{v_\epsilon}G_\epsilon+2\rho'\int_{ \partial M \setminus  B_{R\delta_\epsilon}(x_\epsilon)}  \tilde{h}_\epsilon e^{\frac{v_\epsilon}{2}} G_\epsilon\\
		=&\int_{M \setminus B_{R\delta_\epsilon}(x_\epsilon)} \left(-\Delta v_\epsilon+\frac{2(\rho_\epsilon+\rho')}{|M|}\right)G_\epsilon+2\rho'\int_{ \partial M \backslash B_{R\delta_\epsilon}(x_\epsilon)}  \tilde{h}_\epsilon e^{\frac{v_\epsilon}{2}} G_\epsilon\\
		=&\int_{M \backslash B_{R\delta_\epsilon}(x_\epsilon)} -\Delta G_\epsilon v_\epsilon
		-\int_{ \partial M \backslash B_{R\delta_\epsilon}(x_\epsilon)} \frac{\partial v_\epsilon}{\partial \nu}G_\epsilon+\int_{ \partial M \backslash B_{R\delta_\epsilon}(x_\epsilon)}  v_\epsilon \frac{\partial G_\epsilon}{\partial \nu}+ \int_{ \partial^+ B_{R\delta_\epsilon}(x_\epsilon)} \frac{\partial v_\epsilon}{\partial r}G_\epsilon \\
		&- \int_{ \partial^+ B_{R\delta_\epsilon}(x_\epsilon)} v_\epsilon \frac{\partial G_\epsilon}{\partial r}+\frac{2(\rho_\epsilon+\rho')}{|M|}\int_{M \setminus B_{R\delta_\epsilon}(x_\epsilon)} G_\epsilon+2\rho'\int_{ \partial M \setminus B_{R\delta_\epsilon}(x_\epsilon)}  \tilde{h}_\epsilon e^{\frac{v_\epsilon}{2}} G_\epsilon\\
		=&-\frac{4\pi}{|M|}\int_{M \backslash B_{R\delta_\epsilon}(x_\epsilon)}  v_\epsilon+ \int_{ \partial^+ B_{R\delta_\epsilon}(x_\epsilon)} \frac{\partial v_\epsilon}{\partial r}G_\epsilon - \int_{ \partial^+ B_{R\delta_\epsilon}(x_\epsilon)} v_\epsilon \frac{\partial G_\epsilon}{\partial r}
		+o_\epsilon(1).
	\end{align*}

	Similarly,
	\begin{align*}
		&4\rho_\epsilon \log\delta_\epsilon\int_{M \setminus B_{R\delta_\epsilon}(x_\epsilon)} K e^{v_\epsilon}+4\rho' \log\delta_\epsilon\int_{ \partial M \backslash B_{R\delta_\epsilon}(x_\epsilon)}  \tilde{h}_\epsilon e^{\frac{v_\epsilon}{2}}\\
		=&2\log\delta_\epsilon\int_{M \backslash B_{R\delta_\epsilon}(x_\epsilon)} \left(-\Delta v_\epsilon+\frac{2(\rho_\epsilon+\rho')}{|M|}\right)+4\rho' \log\delta_\epsilon\int_{ \partial M \backslash B_{R\delta_\epsilon}(x_\epsilon)} \tilde{h}_\epsilon e^{\frac{v_\epsilon}{2}} \\
		=& 2\log\delta_\epsilon \int_{\partial^+ B_{R\delta_\epsilon}(x_\epsilon)} \frac{\partial v_\epsilon}{\partial r} +\frac{4(\rho_\epsilon+\rho')}{|M|}\log\delta_\epsilon |M \backslash B_{R\delta_\epsilon}(x_\epsilon)|.
	\end{align*}

	Now, we arrive at
	\begin{align*}
		\int_{M \backslash B_{R\delta_\epsilon}(x_\epsilon)}|\nabla  v_\epsilon|^2
		\geq&-\frac{2(\rho_\epsilon+\rho')}{|M|} \int_{M \backslash B_{R\delta_\epsilon}(x_\epsilon)}v_\epsilon-\int_{ \partial^+ B_{R\delta_\epsilon}(x_\epsilon)}v_\epsilon \frac { \partial v_\epsilon}{\partial r} \\
		&-\frac{4\pi}{|M|}\int_{M \backslash B_{R\delta_\epsilon}(x_\epsilon)}  v_\epsilon + \int_{ \partial^+ B_{R\delta_\epsilon}(x_\epsilon)} \frac{\partial v_\epsilon}{\partial r}G_\epsilon - \int_{\partial^+ B_{R\delta_\epsilon}(x_\epsilon)} v_\epsilon \frac{\partial G_\epsilon}{\partial r}\\
		& +2\log\delta_\epsilon \int_{ \partial^+ B_{R\delta_\epsilon}(x_\epsilon)} \frac{\partial v_\epsilon}{\partial r} +\frac{4(\rho_\epsilon+\rho')}{|M|}\log\delta_\epsilon |M \backslash B_{R\delta_\epsilon}(x_\epsilon)|+o_\epsilon(1) \\
		=&-\frac{2(\rho_\epsilon+\rho'+2\pi)}{|M|} \int_{M \backslash B_{R\delta_\epsilon}(x_\epsilon)}v_\epsilon-\int_{\partial^+ B_{R\delta_\epsilon}(x_\epsilon)}\frac{\partial v_\epsilon}{\partial r}\left(v_\epsilon-G_\epsilon-2\log\delta_\epsilon\right)\\
		&-\int_{\partial^+ B_{R\delta_\epsilon}(x_\epsilon)}v_\epsilon \frac{\partial G_\epsilon}{\partial r}+4(\rho_\epsilon+\rho')\log\delta_\epsilon  + o_\epsilon(1)\\
		:=&\mathbf{I}+\mathbf{II}+\mathbf{III}+4(\rho_\epsilon+\rho')\log\delta_\epsilon + o_\epsilon(1).
	\end{align*}

For $\mathbf{I}$, since $$|v_\epsilon(x)|\leq -2\log\delta_\epsilon+C,\ \ \forall\ x\in B_{R\delta_\epsilon}(x_\epsilon),$$ then \begin{equation*}\left|\int_{B_{R\delta_\epsilon}(x_\epsilon)}v_\epsilon dv_g\right|\leq C(R)\delta_\epsilon^2|\log\delta_\epsilon|=o_\epsilon(1).\end{equation*}
	Computing directly,
	we have
	\begin{align*}
		\mathbf{I}=&-\frac{2(\rho_\epsilon+\rho'+2\pi)}{|M|} \int_{M\setminus B_{R\delta_\epsilon}(x_\epsilon) }v_\epsilon\\ =&-\frac{2(\rho_\epsilon+\rho'+2\pi)}{|M|} \int_{M}v_\epsilon+o_\epsilon (1)\\
		=&-\frac{2(\rho_\epsilon+\rho'+2\pi)}{|M|} \int_{M }(v_\epsilon-\overline{v}_\epsilon) -\frac{2(\rho_\epsilon+\rho'+2\pi)}{|M|} \int_{M }\overline{v}_\epsilon\\
		=&-\frac{2(\rho_\epsilon+\rho'+2\pi)}{|M|}  \int_{M }G_\epsilon-2(\rho_\epsilon+\rho'+2\pi)  \bar{v}_\epsilon+o_\epsilon(1)\\=&-2(\rho_\epsilon+\rho'+2\pi)  \bar{v}_\epsilon+o_\epsilon(1).
	\end{align*}

	By Lemma \ref{lem:02}, we get
	\begin{align*}
		\mathbf{II}=&-\int_{\partial^+ B_{R\delta_\epsilon}(x_\epsilon)}\frac{\partial v_\epsilon}{\partial r}\left(v_\epsilon-G_\epsilon-2\log\delta_\epsilon\right)\\
		\geq& -\int_{\partial^+ B^+_{R}(0)}\frac{\partial w}{\partial r}dS\cdot \left(- A(p)+\log\frac{8\lambda^2}{\tilde{K}(0)} + o_\epsilon(1)+o_R(1)\right) \\
		=& 4\pi \left(- A(p)+\log\frac{8\lambda^2}{\tilde{K}(0)}\right)+ o_\epsilon(1)+o_R(1).
	\end{align*}

	For the term $\mathbf{III}$, since \begin{align*}
v_\epsilon\bigg|_{\partial^+ B_{R\delta_\epsilon}(x_\epsilon)}&=w|_{\partial^+B_R(0)}-2\log\delta_\epsilon+o_\epsilon(1)\\
&=-2\log\delta_\epsilon+\log\frac{8\lambda^2}{\tilde{K}(0)}-2\log\big(\lambda^2+(R-\frac{c\lambda}{\sqrt{2}})^2\big) +o_\epsilon(1)+o_R(1), \end{align*} we obtain
	\begin{align*}
		\mathbf{III}&=-\int_{\partial^+ B_{R\delta_\epsilon}(x_\epsilon)}v_\epsilon \frac{\partial G_\epsilon}{\partial r}\\		&=-\left(-2\log\delta_\epsilon+\log\frac{8\lambda^2}{\tilde{K}(0)}-2\log\big(\lambda^2+(R-\frac{c\lambda}{\sqrt{2}})^2\big)\right) \int_{\partial^+ B_{R\delta_\epsilon}(x_\epsilon)} \frac{\partial G_\epsilon}{\partial r}+o_\epsilon (1)+o_R(1)\\		&=\left(-2\log\delta_\epsilon+\log\frac{8\lambda^2}{\tilde{K}(0)}-2\log\big(\lambda^2+(R-\frac{c\lambda}{\sqrt{2}})^2\big)\right)\int_{M\setminus  B_{R\delta_\epsilon}(x_\epsilon)} \Delta G_\epsilon+o_\epsilon (1)+o_R(1)\\
		&=4\pi\left(-2\log\delta_\epsilon+\log\frac{8\lambda^2}{\tilde{K}(0)} -2\log\big(\lambda^2+(R-\frac{c\lambda}{\sqrt{2}})^2\big)\right)+o_\epsilon (1)+o_R(1).
	\end{align*}

	Combining these together, we have
	\begin{align*}
		&\int_{M \backslash B_{R\delta_\epsilon}(x_\epsilon)}|\nabla  v_\epsilon|^2\\
		\geq& -2(\rho_\epsilon+\rho'+2\pi)  \bar{v}_\epsilon+ 4\pi\left(-A(p)+2\log\frac{8\lambda^2}{\tilde{K}(0)}-2\log(\lambda^2+R^2)\right)-4\epsilon\log\delta_\epsilon+o_\epsilon(1)+o_R(1).
	\end{align*}
	Therefore, we have
	\begin{align*}
		\int_{ M}|\nabla v_\epsilon|^2=&\int_{M \backslash B_{R\delta_\epsilon}(x_\epsilon)}|\nabla  v_\epsilon|^2+\int_{ B_{R\delta_\epsilon}(x_\epsilon)}|\nabla  v_\epsilon|^2\\
		\geq& -2(\rho_\epsilon+\rho'+2\pi)  \bar{v}_\epsilon-4\epsilon\log\delta_\epsilon+ 4\pi\left(-A(p)+2\log\frac{8\lambda^2}{\tilde{K}(0)}-2\log\lambda^2-2\right)\\ & -8\pi\log\frac{2\pi+\rho'}{2\pi-\rho'}+4\rho'+o_\epsilon(1)+o_R(1),
	\end{align*} which implies
	\begin{align*}
		\frac{1}{2}\int_M|\nabla v_\epsilon|^2+\frac{2(\rho_\epsilon+\rho')}{|M|}\int_M v_\epsilon
		\geq&-2\epsilon\log\delta_\epsilon-\epsilon\bar{v}_\epsilon+2\pi\left(-A(p)+2\log\frac{8}{\tilde{K}(0)}-2\right)\\& -4\pi\log\frac{2\pi+\rho'}{2\pi-\rho'}+2\rho'+o_\epsilon(1)+o_R(1)
	\end{align*}

	By \eqref{equation:06}, we have
	\begin{align*}
		J_{\rho_\epsilon,\rho'}(v_\epsilon)\geq& -2\epsilon\log\delta_\epsilon-\epsilon\bar{v}_\epsilon-4\pi-2\pi A(p)+ 4\pi\log 4+2\rho'\\& -2\rho\log K(p)-2\rho'\log h^2(p)-2(2\pi+\rho')\log(2\pi+\rho')+o_\epsilon(1).\end{align*} Hence,
	\begin{align}\label{equation:08}
		\liminf_{\epsilon \to 0}J_{\rho_\epsilon,
			\rho'}(v_\epsilon)\geq& -4\pi+2\rho'+ 4\pi\log 4-2(2\pi+\rho')\log(2\pi+\rho')\notag\\&-2\pi \max_{p\in \partial M}\left(A(p) +\frac{\rho}{\pi}\log K(p)+\frac{\rho'}{\pi}\log h^2(p)\right),\end{align} where $\rho+\rho'=2\pi$.

\label{lem:04}
		Let  $G(x, p)$ be the Green function defined by \eqref{eq:intro-green-function}. Let $p\in\partial M$ and $\Pi(p)$, $\kappa(p)$ be the Gaussian curvature and geodesic curvature of $(M, g)$ and $\partial M$ at $p$ respectively. Then the following identity holds
		$$b_2=-2\kappa,\ \ \ \frac{2\pi}{3}\Pi+c_1\pi+c_3\pi=\frac{2\pi^2}{|M|}.$$

\label{lem:bubble-gradient}
		As $\epsilon\to0$, we have
		\begin{align}
			\frac12\int_{M\cap\{r_\epsilon\leq R_\epsilon\}}
			|\nabla_g\phi_{\epsilon,\delta}|^2\,dv_g
			={}&8\pi\log\alpha-4\pi
			-8\pi\log\bigl(a+\sqrt{1+a^2}\bigr)
			+\frac{4\pi a}{\sqrt{1+a^2}} \notag\\
			&+\frac{16a}{\alpha}+\frac{8\pi}{\alpha^2}
			-8\bigl(b_2(p)+\kappa(p)\bigr)R_\epsilon \notag\\
			&+\left(
			4\pi\sqrt{1+a^2}\,b_2(p)
			+\frac{2\pi\kappa(p)(2a^2+3)}{\sqrt{1+a^2}}
			\right)\sqrt{\epsilon}
			+o(\sqrt{\epsilon}).
			\label{eq:bubble-gradient}
		\end{align}

Noting that $r^2\leq C(r_\epsilon^2+\epsilon)$, $$|\nabla_g\phi_{\epsilon,\delta}|^2=|D\phi_{\epsilon,\delta}|^2+(g^{-2}-r^{-2}) |\frac{\partial}{\partial\theta}\phi_{\epsilon,\delta}|^2$$ and
		\begin{align*}
			\int_{\{r_\epsilon\leq R_\epsilon\}}|g^{-2}-r^{-2}||\frac{\partial}{\partial\theta}\phi_{\epsilon,\delta}|^2 dv_g&= \int_{\{r_\epsilon\leq R_\epsilon\}}\left|\frac{\Pi}{3}+O(r)\right|\left| \frac{-4a\sqrt{\epsilon}r\cos\theta}{r_\epsilon^2+\epsilon}-b_1r\sin\theta+b_2r\cos\theta\right|^2 dv_g\\&\leq C\int_{\{r_\epsilon\leq R_\epsilon\}}\left(\left| \frac{4a\sqrt{\epsilon}r\cos\theta}{r_\epsilon^2+\epsilon}\right|^2+r^2 \right)dx\\
			&\leq C\epsilon\int_{\{r_\epsilon\leq R_\epsilon\}}\frac{1}{r_\epsilon^2+\epsilon}dx+C(\alpha\sqrt{\epsilon})^4 \leq C(\alpha\sqrt{\epsilon})^4+C\epsilon\log\alpha\\&=o(\sqrt{\epsilon}) ,
		\end{align*} and

		\begin{align*}
			\int_{\{r_\epsilon\leq R_\epsilon\}}|D\phi_{\epsilon,\delta}|^2r^2dx&\leq C\int_{\{r_\epsilon\leq R_\epsilon\}}\left(\frac{r_\epsilon^2}{(\epsilon+r_\epsilon^2)^2}+1\right)r^2dx\\
			&\leq C \int_{\{r_\epsilon\leq R_\epsilon\}}\frac{r_\epsilon^2}{\epsilon+r_\epsilon^2}dx+ C(\alpha\sqrt{\epsilon})^4\\
			&\leq C(\alpha\sqrt{\epsilon})^2=o(\sqrt{\epsilon}),
		\end{align*}	
		we have
		\begin{align*}
			\int_{\{r_\epsilon\leq R_\epsilon\}}|\nabla_g\phi_{\epsilon,\delta}|^2dv_g= \int_{\{r_\epsilon\leq R_\epsilon\}}|D\phi_{\epsilon,\delta}|^2dv_g+ o(\sqrt{\epsilon})= \int_{\{r_\epsilon\leq R_\epsilon\}\cap M}|D\phi_{\epsilon,\delta}|^2dx+ o(\sqrt{\epsilon}).
		\end{align*}

		\

		\noindent\textbf{Step 1:} Compute $\int_{\{r_\epsilon\leq R_\epsilon\}\cap M}|D (2\log (\epsilon+r_\epsilon^2))|^2dx$.

		\

		It is easy to see that
		\begin{equation}
			\int_{\{r_\epsilon\leq R_\epsilon\}\cap M}|D (2\log (\epsilon+r_\epsilon^2))|^2dx=16\int_{\{x=(x_1,x_2),r_\epsilon\leq R_\epsilon,x_2\geq f(x_1)\}}\frac{r_\epsilon^2}{(\epsilon+r_\epsilon^2)^2}dx,
		\end{equation} where $x_2=f(x_1)=\frac{\kappa(p)}{2}x_1^2+O(x_1^3)$ is the local representation of $\partial M$.

		Setting
		$$
		y_1=\frac{x_1}{\sqrt{\epsilon}},
		\qquad
		y_2=\frac{x_2+a\sqrt{\epsilon}}{\sqrt{\epsilon}},
		$$ then
		$$
		\int_{\{r_\epsilon\leq R_\epsilon\}\cap M}|D (2\log (\epsilon+r_\epsilon^2))|^2dx
		=
		16\int_{\Omega}
		\frac{|y|^2}{(1+|y|^2)^2}\,dy,
		$$
		where $$\Omega:=\{y=(y_1,y_2)| \ y\in B_\alpha(0), y_2\geq a+\frac{f(y_1\sqrt{\epsilon})}{\sqrt{\epsilon}}=a+d_\epsilon(y_1)\}$$ and $$d_\epsilon(y_1)=\frac{\kappa(p)}{2}\sqrt{\epsilon}y_1^2+O(\epsilon y_1^3).$$		


		Denote  $\Omega=B^+_\alpha(0)\setminus (\Omega_1\cup\Omega_2)$ where
		\begin{align*}
			\Omega_1&:=\{y=(y_1,y_2)\in\mathbb R^2\ |\ |y|\leq \alpha,\ 0\leq y_2\leq a\},\\
			\Omega_2&:=\{y=(y_1,y_2)\in\mathbb R^2\ |\ |y|\leq \alpha,\ a\leq y_2\leq a+d_\epsilon(y_1)\}.
		\end{align*}		
		Firstly, a direct computation yields
		\begin{align}\label{equation:09}
			16\int_{B^+_\alpha(0)}
			\frac{|y|^2}{(1+|y|^2)^2}\,dy&=8\pi\log (\alpha^2+1)+\frac{8\pi}{\alpha^2+1}-8\pi\notag\\
			&=16\pi\log \alpha+\frac{16\pi}{\alpha^2}-8\pi+O(\frac{1}{\alpha^4}).
		\end{align}		
		Secondly, noting that
		\begin{align*}
			32\int_0^a\int_0^{\sqrt{\alpha^2-y_2^2}}\frac{1}{1+|y|^2}\,dy&=32\int_0^a\frac{1}{\sqrt{1+y_2^2}} \arctan\frac{\sqrt{\alpha^2-y_2^2}}{\sqrt{1+y_2^2}}dy_2\\
			&=32\int_0^a\frac{1}{\sqrt{1+y_2^2}} \left(\frac{\pi}{2}- \frac{\sqrt{1+y_2^2}}{\sqrt{\alpha^2-y_2^2}}+O(\frac{1}{\alpha^3}) \right)dy_2\\
			&=16\pi\log (\sqrt{1+a^2}+a)-32\frac{a}{\alpha}+O(\frac{1}{\alpha^3})
		\end{align*}
		and
		\begin{align}\label{equation:07}
			&-32\int_0^a\int_0^{\sqrt{\alpha^2-y_2^2}}\frac{1}{(1+|y|^2)^2}\,dy\notag\\&=-16\int_0^a\frac{1}{(\sqrt{1+y_2^2})^3} \arctan\frac{\sqrt{\alpha^2-y_2^2}}{\sqrt{1+y_2^2}}dy_2-16\int_0^a\frac{1}{1+y_2^2} \frac{\sqrt{\alpha^2-y_2^2}}{\alpha^2+1}dy_2\notag\\
			&=-16\int_0^a\frac{1}{(\sqrt{1+y_2^2})^3} \left(\frac{\pi}{2}- \frac{\sqrt{1+y_2^2}}{\sqrt{\alpha^2-y_2^2}}+O(\frac{1}{\alpha^3}) \right) dy_2 -\frac{16\alpha}{\alpha^2+1}\int_0^a\frac{1}{1+y_2^2} \left( 1+O(\frac{1}{\alpha^2})\right)dy_2\notag\\
			&=-8\pi\int_0^a\frac{1}{(\sqrt{1+y_2^2})^3} dy_2+\frac{16}{\alpha}\int_0^a\frac{1}{1+y_2^2}(1+O(\frac{1}{\alpha^2})) dy_2 -\frac{16\alpha}{\alpha^2+1}\int_0^a\frac{1}{1+y_2^2} dy_2\notag\\
			&\quad +O(\frac{1}{\alpha^3})\notag\\
			&=-8\pi\frac{a}{\sqrt{1+a^2}}+O(\frac{1}{\alpha^3}),
		\end{align}
		we get
		\begin{align}\label{equation:10}
			16\int_{\Omega_1}
			\frac{|y|^2}{(1+|y|^2)^2}\,dy&=32\int_0^a\int_0^{\sqrt{\alpha^2-y_2^2}}\frac{|y|^2}{(1+|y|^2)^2}\,dy\notag\\
			&=16\pi\log (\sqrt{1+a^2}+a)-8\pi\frac{a}{\sqrt{1+a^2}}-32\frac{a}{\alpha}+O(\frac{1}{\alpha^3}).
		\end{align}

		Thirdly, let $t_\epsilon^-<0<t_\epsilon^+$ and $(t_\epsilon^-,a+d_\epsilon(t_\epsilon^-))$, $(t_\epsilon^+,a+d_\epsilon(t_\epsilon^+))$ are the two intersection points of the curve $y_2=\sqrt{\alpha^2-y_1^2}$ and the curve $y_2=a+d_\epsilon(y_1)$. Then we have $$(t_\epsilon^\pm)^2+(a+d_\epsilon(t_\epsilon^\pm))^2=\alpha^2$$ and
		\begin{align*}
			\sqrt{\alpha^2-a^2}-|t_\epsilon^\pm|=\frac{2ad_\epsilon(t_\epsilon^\pm)+ (d_\epsilon(t_\epsilon^\pm))^2}{\sqrt{\alpha^2-a^2}+|t_\epsilon^\pm|} \leq C\frac{d_\epsilon(t_\epsilon^\pm)}{|t_\epsilon^\pm|}\leq C\alpha\sqrt{\epsilon},
		\end{align*} which implies $\frac{1}{2}\alpha<|t_\epsilon^\pm|<\alpha$.

		Thus,
		\begin{align*}
			\int_{t_\epsilon^+}^{\sqrt{\alpha^2-a^2}} \int_a^{a+d_\epsilon(y_1)}\frac{|y|^2}{(1+|y|^2)^2}\,dy&\leq  \int_{t_\epsilon^+}^{\sqrt{\alpha^2-a^2}} \int_a^{a+d_\epsilon(\sqrt{\alpha^2-a^2})}\frac{1}{|y|^2}\,dy\\
			&\leq \frac{C}{(t_\epsilon^+)^2}\alpha\sqrt{\epsilon}\alpha^2\sqrt{\epsilon}\leq C\alpha\epsilon=o(\sqrt{\epsilon}).
		\end{align*}
		Similarly, $$\int^{t_\epsilon^-}_{-\sqrt{\alpha^2-a^2}} \int_a^{a+d_\epsilon(y_1)}\frac{|y|^2}{(1+|y|^2)^2}\,dy=o(\sqrt{\epsilon}).$$
		Therefore,
		\begin{align*}
			16\int_{\Omega_2}
			\frac{|y|^2}{(1+|y|^2)^2}\,dy&=16\int_{-\sqrt{\alpha^2-a^2}}^{\sqrt{\alpha^2-a^2}} \int_a^{a+d_\epsilon(y_1)}\frac{|y|^2}{(1+|y|^2)^2}\,dy+ o(\sqrt{\epsilon}).
		\end{align*}

		Computing directly, we obtain
		\begin{align*}
			&\int_{-\sqrt{\alpha^2-a^2}}^{\sqrt{\alpha^2-a^2}} \int_a^{a+d_\epsilon(y_1)}\left|\frac{|y|^2}{(1+|y|^2)^2}-\frac{y_1^2+a^2}{(1+y_1^2+a^2)^2}\right| \,dy \\ &\leq C\int_{-\sqrt{\alpha^2-a^2}}^{\sqrt{\alpha^2-a^2}} \int_a^{a+d_\epsilon(y_1)}\frac{(y_1^2+a^2)(1+|y|^2)+(1+|y|^2)^2}{(1+y_1^2+a^2)^2(1+|y|^2)^2}d_\epsilon(y_1)\,dy\\
			&\leq C\int_{-\sqrt{\alpha^2-a^2}}^{\sqrt{\alpha^2-a^2}} \frac{1}{(1+y_1^2+a^2)^2}d^2_\epsilon(y_1)\,dy_1\leq C\alpha\epsilon=o(\sqrt{\epsilon})
		\end{align*}
		and
		\begin{align*}
			&16\int_{-\sqrt{\alpha^2-a^2}}^{\sqrt{\alpha^2-a^2}} \int_a^{a+d_\epsilon(y_1)}\frac{y_1^2+a^2}{(1+y_1^2+a^2)^2} \,dy \\ &=16\int_{-\sqrt{\alpha^2-a^2}}^{\sqrt{\alpha^2-a^2}}\frac{y_1^2+a^2}{(1+y_1^2+a^2)^2} \left(\frac{\kappa(p)}{2}\sqrt{\epsilon}y_1^2+O(\epsilon |y_1|^3)\right)\,dy_1\\
			&=16\kappa(p)\sqrt{\epsilon}\left(\sqrt{\alpha^2-a^2}+\frac{\sqrt{\alpha^2-a^2}}{2(\alpha^2+1)}- \frac{2a^2+3}{2\sqrt{a^2+1}}\arctan\frac{\sqrt{\alpha^2-a^2}}{\sqrt{1+a^2}}\right)+O(\alpha^2\epsilon)\\
			&=16\kappa(p)\alpha\sqrt{\epsilon}-4\pi \kappa(p)\frac{2a^2+3}{\sqrt{a^2+1}}\sqrt{\epsilon}+o(\sqrt{\epsilon}).
		\end{align*}

		Then
		\begin{align}\label{equation:11}
			16\int_{\Omega_2}
			\frac{|y|^2}{(1+|y|^2)^2}\,dy&=16\kappa(p)\alpha\sqrt{\epsilon}-4\pi \kappa(p)\frac{2a^2+3}{\sqrt{a^2+1}}\sqrt{\epsilon}+o(\sqrt{\epsilon}).
		\end{align}

		Combining \eqref{equation:09}-\eqref{equation:11}, we get
		\begin{align}
			\frac{1}{2}\int_{\{r_\epsilon\leq R_\epsilon\}\cap M}|D (2\log (\epsilon+r_\epsilon^2))|^2dx
			&=
			8\pi\log\alpha-4\pi
			-8\pi\log\bigl(a+\sqrt{1+a^2}\bigr)
			+\frac{4\pi a}{\sqrt{1+a^2}}
			+\frac{16a}{\alpha}
			+\frac{8\pi}{\alpha^2} \notag\\
			&\quad
			-8\kappa(p)\alpha\sqrt{\epsilon}
			+\frac{2\pi\kappa(p)(2a^2+3)}
			{\sqrt{1+a^2}}\sqrt{\epsilon}
			+o(\sqrt{\epsilon}).
			\label{eq:bubble-radial-complete}
		\end{align}



		\

		\noindent\textbf{Step 2:} Compute $\int_{\{r_\epsilon\leq R_\epsilon\}\cap M}D (-2\log (\epsilon+r_\epsilon^2))D(b_1x_1+b_2x_2)dx$.

		\

		It is easy to see that
		\begin{align*}
			&\int_{\{r_\epsilon\leq R_\epsilon\}\cap M}D (-2\log (\epsilon+r_\epsilon^2))D(b_1x_1+b_2x_2)dx\\
			&=\int_{\{x=(x_1,x_2),r_\epsilon\leq R_\epsilon,x_2\geq f(x_1)\}}\left(-\frac{4b_1 x_1}{\epsilon+r_\epsilon^2}- \frac{4b_2 (x_2+a\sqrt{\epsilon})}{\epsilon+r_\epsilon^2}\right)dx\\
			&=\sqrt{\epsilon}\int_\Omega \left(-\frac{4b_1 y_1}{1+|y|^2}- \frac{4b_2 y_2}{1+|y|^2}\right)dy.
		\end{align*}


		On one hand, by symmetry, we have
		\begin{align*}
			-4b_1\sqrt{\epsilon}\int_\Omega \frac{ y_1}{1+|y|^2}dy&= 4b_1\sqrt{\epsilon}\int_{\Omega_2} \frac{ y_1}{1+|y|^2}dy\\
			&=4b_1\sqrt{\epsilon}\int_{-\sqrt{\alpha^2-a^2}}^{\sqrt{\alpha^2-a^2}} \int_a^{a+d_\epsilon(y_1)}\frac{ y_1}{1+|y|^2}\,dy+ o(\sqrt{\epsilon})\\
			&=4b_1\sqrt{\epsilon}\int_{-\sqrt{\alpha^2-a^2}}^{\sqrt{\alpha^2-a^2}} \int_a^{a+d_\epsilon(y_1)}\frac{ y_1}{1+|y_1|^2+a^2}\,dy+ o(\sqrt{\epsilon})\\
			&=4b_1\sqrt{\epsilon}\int_{-\sqrt{\alpha^2-a^2}}^{\sqrt{\alpha^2-a^2}}\frac{ y_1}{1+|y_1|^2+a^2}\left(\frac{\kappa(p)}{2}\sqrt{\epsilon}y_1^2+O(\epsilon |y_1|^3)\right) \,dy_1+ o(\sqrt{\epsilon})\\
			&=o(\sqrt{\epsilon}).
		\end{align*}

		On the other hand, noting that
		\begin{align*}
			\int_{\Omega\cup\Omega_2} \frac{ y_2}{1+|y|^2}dy&= \int_{-\sqrt{\alpha^2-a^2}}^{\sqrt{\alpha^2-a^2}}\int_a^{\sqrt{\alpha^2-y_1^2}} \frac{ y_2}{1+|y|^2}dy\\
			&=2\sqrt{\alpha^2-a^2}-2\sqrt{1+a^2}\arctan\sqrt{\frac{\alpha^2-a^2}{1+a^2}}\\
			&=2\alpha(1-\frac{1}{2}\frac{a^2}{\alpha^2}+O(\alpha^{-4})) -2\sqrt{1+a^2}\left(\frac{\pi}{2}-\sqrt{\frac{1+a^2}{\alpha^2-a^2}}+O(\alpha^{-3})\right)\\
			&=2\alpha-\pi\sqrt{1+a^2}+\frac{2+a^2}{\alpha}+O(\alpha^{-3})
		\end{align*}
		and
		\begin{align*}
			\int_{\Omega_2} \frac{ y_2}{1+|y|^2}dy&= \int_{-\sqrt{\alpha^2-a^2}}^{\sqrt{\alpha^2-a^2}}\int_a^{a+d_\epsilon(y_1)} \frac{ y_2}{1+|y|^2}dy+o(\sqrt{\epsilon})\\
			&= \int_{-\sqrt{\alpha^2-a^2}}^{\sqrt{\alpha^2-a^2}}\int_a^{a+d_\epsilon(y_1)} \frac{ a}{1+a^2+y_1^2}dy+o(\sqrt{\epsilon})+O(\alpha^3\epsilon)=O(\alpha\sqrt\epsilon),
		\end{align*}
		we have
		\begin{align*}
			-4b_2\sqrt{\epsilon}\int_\Omega \frac{ y_2}{1+|y|^2}dy= -8b_2\alpha\sqrt{\epsilon}+4\pi b_2\sqrt{1+a^2}\sqrt{\epsilon}+o(\sqrt{\epsilon}).
		\end{align*}		
		Then
		\begin{align*}
			\int_{\{r_\epsilon\leq R_\epsilon\}\cap M}D (-2\log (\epsilon+r_\epsilon^2))D(b_1x_1+b_2x_2)dx= -8b_2\alpha\sqrt{\epsilon}+4\pi b_2\sqrt{1+a^2}\sqrt{\epsilon}+o(\sqrt{\epsilon}).
		\end{align*}









		Finally, noting that
		\begin{equation}\label{eq:bubble-constant-gradient}
			\frac12\bigl(b_1(p)^2+b_2(p)^2\bigr)
			\int_{\{r_\epsilon\leq R_\epsilon\}\cap M}dx
			=
			O(\alpha^2\epsilon)
			=
			o(\sqrt{\epsilon}).
		\end{equation}
		we obtain
		\begin{align*}
			\frac12\int_{M\cap\{r_\epsilon\leq R_\epsilon\}}
			|\nabla_g\phi_{\epsilon,\delta}|^2\,dv_g
			=&8\pi\log\alpha-4\pi
			-8\pi\log\bigl(a+\sqrt{1+a^2}\bigr)
			+\frac{4\pi a}{\sqrt{1+a^2}}\\
			&+\frac{16a}{\alpha}+\frac{8\pi}{\alpha^2}
			-8\bigl(b_2(p)+\kappa(p)\bigr)R_\epsilon\\
			&+\left(
			4\pi\sqrt{1+a^2}\,b_2(p)
			+\frac{2\pi\kappa(p)(2a^2+3)}{\sqrt{1+a^2}}
			\right)\sqrt{\epsilon}
			+o(\sqrt{\epsilon}).
		\end{align*}
		This proves \eqref{eq:bubble-gradient}.

\label{lem:neck-gradient}
		As $\epsilon\to0$, we have
		\begin{align}
			\frac12\int_{M\cap\{R_\epsilon<r_\epsilon<2R_\epsilon\}}
			|\nabla_g\phi_{\epsilon,\delta}|^2\,dv_g
			=8\pi\log2-\frac{8a}{\alpha}-\frac{6\pi}{\alpha^2}-8\bigl(b_2(p)+\kappa(p)\bigr)R_\epsilon
			+o(\sqrt{\epsilon}).
			\label{eq:neck-gradient}
		\end{align}

\label{lem:exterior-gradient}
		For every fixed  small constant $\delta>0$, as $\epsilon\to0$, we have
		\begin{align}
			\frac12\int_{M\cap\{r_\epsilon\geq2R_\epsilon\}}
			|\nabla_g\phi_{\epsilon,\delta}|^2\,dv_g
			={}&-8\pi\log(2R_\epsilon)+2\pi A(p)
			-\frac{8a}{\alpha}-\frac{2\pi}{\alpha^2} \notag\\
			&+16\bigl(b_2(p)+\kappa(p)\bigr)R_\epsilon
			+O(\delta\sqrt{\epsilon})
			+o(\sqrt{\epsilon}).
			\label{eq:exterior-gradient}
		\end{align}

\noindent\textbf{Step 1:} Compute $\frac12\int_{M\cap\{r\geq2R_\epsilon\}}|\nabla_gG|^2\,dv_g$.

		\





		Integrating by parts, we get
		\begin{align*}
			\frac12\int_{M\cap\{r\geq2R_\epsilon\}}|\nabla_gG|^2\,dv_g &=-\frac12\int_{M\cap\{r\geq2R_\epsilon\}}\Delta_gG\cdot G\,dv_g +\frac12\int_{M\cap\{r=2R_\epsilon\}}G(-\partial_rG)\,ds_g\\
			&=\frac{2\pi}{|M|}\int_{M\cap\{r<2R_\epsilon\}}G\,dv_g
			+\frac12\int_{M\cap\{r=2R_\epsilon\}}G(-\partial_rG)\,ds_g.
		\end{align*}
		Since the divergence theorem yields
		$$
		\int_{M\cap\{r=2R_\epsilon\}}(-\partial_rG)\,ds_g
		=
		4\pi-\frac{4\pi}{|M|}
		\operatorname{Vol}_g\bigl(M\cap\{r<2R_\epsilon\}\bigr),
		$$
		then
		\begin{align}
			\frac12\int_{M\cap\{r\geq2R_\epsilon\}}|\nabla_gG|^2\,dv_g
			={}&-8\pi\log(2R_\epsilon)+2\pi A(p) \notag\\
			&+\frac12\int_{M\cap\{r=2R_\epsilon\}}
			\bigl[G+4\log(2R_\epsilon)-A(p)\bigr](-\partial_rG)\,ds_g \notag\\
			&+\frac{2\pi}{|M|}\int_{M\cap\{r<2R_\epsilon\}}
			\bigl[G+4\log(2R_\epsilon)-A(p)\bigr]\,dv_g.
			\label{eq:green-energy-exterior-reduction}
		\end{align}

		For $r<2R_\epsilon$,
		$$
		G+4\log(2R_\epsilon)-A(p)
		=
		-4\log\frac{r}{2R_\epsilon}+b_1(p)x_1+b_2(p)x_2+O(r^2).
		$$
		Since
		$$
		\int_0^{2R_\epsilon}\left|\log\frac{r}{2R_\epsilon}\right|r\,dr=O(R_\epsilon^2),
		$$
		we have
		$$
		\int_{M\cap\{r<2R_\epsilon\}}
		\bigl[G+4\log(2R_\epsilon)-A(p)\bigr]\,dv_g
		=
		O(R_\epsilon^2)=o(\sqrt{\epsilon}).
		$$

		On $r=2R_\epsilon$, we have
		$$
		G+4\log(2R_\epsilon)-A(p)
		=
		2R_\epsilon\bigl(b_1(p)\cos\theta+b_2(p)\sin\theta\bigr)+O(R_\epsilon^2),
		$$
		$$
		-\partial_rG
		=
		\frac{2}{R_\epsilon}-b_1(p)\cos\theta-b_2(p)\sin\theta+O(R_\epsilon),
		\quad
		ds_g=2R_\epsilon\bigl(1+O(R_\epsilon^2)\bigr)\,d\theta.
		$$
		Let $\theta_+$ and $\theta_-$ be defined so that the two endpoints of the circular arc $r=2R_\epsilon$ correspond to the polar angles $\theta_+$ and $\pi-\theta_-$, respectively. Then by the proof of Lemma \ref{lem:04}, we have
		$$
		\theta_+=\kappa(p)R_\epsilon+O(R_\epsilon^2),
		\qquad
		\theta_-=\kappa(p)R_\epsilon+O(R_\epsilon^2),
		$$
		and
		\begin{align*}
			\int_{\theta_+}^{\pi-\theta_-}\cos\theta\,d\theta
			=\sin\theta_- -\sin\theta_+=O(R_\epsilon^2),\
			\int_{\theta_+}^{\pi-\theta_-}\sin\theta\,d\theta
			=\cos\theta_++\cos\theta_-=2+O(R_\epsilon^2).
		\end{align*}
		Therefore,
		\begin{align*}
			&\frac12\int_{M\cap\{r=2R_\epsilon\}}
			\left(G+4\log(2R_\epsilon)-A(p)\right)(-\partial_rG)\,ds_g\\
			&=
			4R_\epsilon\int_{\theta_+}^{\pi-\theta_-}
			\bigl(b_1(p)\cos\theta+b_2(p)\sin\theta\bigr)\,d\theta
			+O(R_\epsilon^2)=
			8b_2(p)R_\epsilon+O(R_\epsilon^2).
		\end{align*}
		Substituting these estimates into
		\eqref{eq:green-energy-exterior-reduction}, and using
		$b_2(p)=-2\kappa(p)$ and $R_\epsilon^2=o(\sqrt{\epsilon})$, we obtain
		\begin{equation}\label{eq:complete-green-energy-exterior-final}
			\frac12\int_{M\cap\{r\geq2R_\epsilon\}}|\nabla_gG|^2\,dv_g
			=
			-8\pi\log(2R_\epsilon)+2\pi A(p)
			+16\bigl(b_2(p)+\kappa(p)\bigr)R_\epsilon
			+o(\sqrt{\epsilon}).
		\end{equation}


		\

		\noindent\textbf{Step 2:} Compute $\frac12\int_{M\cap\{r_\epsilon\geq2R_\epsilon,\ r\leq\delta\}}
		|\nabla_g\phi_{\epsilon,\delta}|^2\,dv_g-\frac12\int_{M\cap\{2R_\epsilon\leq r\leq\delta\}}
		|\nabla_gG|^2\,dv_g $.

		\




		In $M\cap\{r_\epsilon\geq2R_\epsilon,\ r\leq\delta\}$, we have
		\begin{align*}
			\nabla_g\phi_{\epsilon,\delta}
			=&
			\nabla_g\bigl[-2\log(\epsilon+r_\epsilon^2)\bigr]
			+
			\nabla_g\bigl(G(x,p)+4\log r\bigr),\\
			\nabla_gG
			=&
			\nabla_g(-4\log r)
			+
			\nabla_g\bigl(G(x,p)+4\log r\bigr).
		\end{align*}
		Then
		\begin{align*}
			&\frac12\int_{M\cap\{r_\epsilon\geq2R_\epsilon,\ r\leq\delta\}}
			|\nabla_g\phi_{\epsilon,\delta}|^2\,dv_g
			-
			\frac12\int_{M\cap\{2R_\epsilon\leq r\leq\delta\}}
			|\nabla_gG|^2\,dv_g \notag\\
			&=
			\frac12\int_{M\cap\{r_\epsilon\geq2R_\epsilon,\ r\leq\delta\}}
			\left|\nabla_g\bigl[-2\log(\epsilon+r_\epsilon^2)\bigr]\right|^2\,dv_g
			-
			\frac12\int_{M\cap\{2R_\epsilon\leq r\leq\delta\}}
			|\nabla_g(-4\log r)|^2\,dv_g \notag\\
			&\quad+
			\int_{M\cap\{r_\epsilon\geq2R_\epsilon,\ r\leq\delta\}}
			\left\langle
			\nabla_g\bigl[-2\log(\epsilon+r_\epsilon^2)\bigr],
			\nabla_g\bigl(G(x,p)+4\log r\bigr)
			\right\rangle_g\,dv_g \notag\\
			&\quad-
			\int_{M\cap\{2R_\epsilon\leq r\leq\delta\}}
			\left\langle
			\nabla_g(-4\log r),
			\nabla_g\bigl(G(x,p)+4\log r\bigr)
			\right\rangle_g\,dv_g \notag\\
			&\quad+
			\frac12\int_{M\cap\{r_\epsilon\geq2R_\epsilon,\ r\leq\delta\}}
			\left|\nabla_g\bigl(G(x,p)+4\log r\bigr)\right|^2\,dv_g -
			\frac12\int_{M\cap\{2R_\epsilon\leq r\leq\delta\}}
			\left|\nabla_g\bigl(G(x,p)+4\log r\bigr)\right|^2\,dv_g\\
			&:=\mathbf{I_1}+\mathbf{I_2}+\mathbf{I_3}.
		\end{align*}

		For $\mathbf{I_1}$, noting that
		\begin{align*}
			\int_{\{r_\epsilon\leq \delta\}}|g^{-2}-r^{-2}||\frac{\partial}{\partial\theta}(-2\log(\epsilon+r_\epsilon^2))|^2 dv_g&= \int_{\{r_\epsilon\leq \delta\}}\left|\frac{\Pi}{3}+O(r)\right|\left| \frac{4a\sqrt{\epsilon}r\cos\theta}{r_\epsilon^2+\epsilon}\right|^2 dv_g\\&\leq C\int_{\{r_\epsilon\leq \delta\}}\left(\left| \frac{4a\sqrt{\epsilon}r\cos\theta}{r_\epsilon^2+\epsilon}\right|^2 \right)dx\\
			&\leq C\epsilon\int_{\{r_\epsilon\leq \delta\}}\frac{1}{r_\epsilon^2+\epsilon}dx\leq C\epsilon\log\alpha=o(\sqrt{\epsilon})
		\end{align*} and
		$$
		\left|D\bigl[-2\log(\epsilon+r_\epsilon^2)\bigr]\right|^2
		-|D(-4\log r)|^2=O(\frac{\sqrt{\epsilon}x_2+\epsilon}{r^4}),\ for\  r_\epsilon\geq2R_\epsilon,\ 2R_\epsilon\leq  r\leq\delta,
		$$
		we have
		\begin{align*}
			\mathbf{I_1}
			&=\frac12\int_{M\cap\{r_\epsilon\geq2R_\epsilon,\ r\leq\delta\}}
			\left|D\bigl[-2\log(\epsilon+r_\epsilon^2)\bigr]\right|^2\,dv_g
			-\frac12\int_{M\cap\{2R_\epsilon\leq r\leq\delta\}}
			|D(-4\log r)|^2\,dv_g +o(\sqrt{\epsilon})\notag\\
			&=
			\frac12\int_{M\cap\{r_\epsilon\geq2R_\epsilon,\ 2R_\epsilon\leq  r\leq\delta\}}
			\left(
			\left|D\bigl[-2\log(\epsilon+r_\epsilon^2)\bigr]\right|^2
			-|D(-4\log r)|^2
			\right)dv_g +o(\sqrt{\epsilon})\notag\\
			&\quad+
			\frac12\int_{M\cap\{r_\epsilon\geq2R_\epsilon,\ r<2R_\epsilon\}}
			\left|D\bigl[-2\log(\epsilon+r_\epsilon^2)\bigr]\right|^2\,dv_g -
			\frac12\int_{M\cap\{r\geq2R_\epsilon,\ r_\epsilon<2R_\epsilon\}}
			|D(-4\log r)|^2\,dv_g\\
			&=
			\frac12\int_{M\cap\{r_\epsilon\geq2R_\epsilon,\ 2R_\epsilon\leq  r\leq\delta\}}
			\left(
			\left|D\bigl[-2\log(\epsilon+r_\epsilon^2)\bigr]\right|^2
			-|D(-4\log r)|^2
			\right)dx +o(\sqrt{\epsilon})+O(\delta\sqrt{\epsilon})\\
			&\quad+
			\frac12\int_{M\cap\{r_\epsilon\geq2R_\epsilon,\ r<2R_\epsilon\}}
			\left|D\bigl[-2\log(\epsilon+r_\epsilon^2)\bigr]\right|^2\,dx -
			\frac12\int_{M\cap\{r\geq2R_\epsilon,\ r_\epsilon<2R_\epsilon\}}
			|D(-4\log r)|^2\,dx.
		\end{align*}





		Since
		\begin{align*}
			\{r_\epsilon\geq2R_\epsilon,\ r<2R_\epsilon, \ 0\leq x_2\leq f(x_1)\}\subset \{\sqrt{4R_\epsilon^2-(x_2+a\sqrt{\epsilon})^2}\leq |x_1|\leq 2R_\epsilon, \ 0\leq x_2\leq f(x_1)\}
		\end{align*} and $$2R_\epsilon-\sqrt{4R_\epsilon^2-(x_2+a\sqrt{\epsilon})^2}=O(\frac{\epsilon}{R_\epsilon})=o(\sqrt{\epsilon}),$$
		we get
		\begin{align*}
			&\int_{\{r_\epsilon\geq2R_\epsilon,\ r<2R_\epsilon, \ 0\leq x_2\leq f(x_1)\}}
			\left|D\bigl[-2\log(\epsilon+r_\epsilon^2)\bigr]\right|^2\,dx=o(\sqrt{\epsilon}).
		\end{align*}
		Similarly,
		\begin{align*}
			\int_{\{r\geq2R_\epsilon,\ r_\epsilon<2R_\epsilon, \ 0\leq x_2\leq f(x_1)\}}
			|D(-4\log r)|^2\,dx=o(\sqrt{\epsilon}).
		\end{align*}

		Noting that
		\begin{align*}
			&\int_{\{r_\epsilon\geq2R_\epsilon,\ 2R_\epsilon\leq  r\leq\delta,\ 0\leq x_2\leq f(x_1)\}}
			\left|
			\left|D\bigl[-2\log(\epsilon+r_\epsilon^2)\bigr]\right|^2
			-|D(-4\log r)|^2
			\right|dx\\& \leq C\int_{R_\epsilon}^\delta\int_0^{f(x_1)}\frac{\sqrt{\epsilon}x_2+\epsilon}{r^4}dx_2dx_1=O(\delta\sqrt{\epsilon})+o(\sqrt{\epsilon}),
		\end{align*}
		we have
		\begin{align*}
			\mathbf{I_1}
			&=\frac12\int_{\{r_\epsilon\geq2R_\epsilon,\ r\leq\delta,\ x_2\geq 0\}}
			\left|D\bigl[-2\log(\epsilon+r_\epsilon^2)\bigr]\right|^2\,dx
			-\frac12\int_{\{2R_\epsilon\leq r\leq\delta, \ x_2\geq 0\}}
