		In this case, we have
		\begin{align*}
			&\frac12\int_{M\cap\{ r\geq\delta\}}
			|\nabla_g\phi_{\epsilon,\delta}|^2\,dv_g-\frac12\int_{M\cap\{r\geq\delta\}}
			|\nabla_gG|^2\,dv_g\\
			&=\int_{M\cap\{ r\geq\delta\}}
			\nabla_g G \nabla_g\left(\eta_\delta (4\log r-2\log (\epsilon+r_\epsilon^2))\right)\,dv_g+ \frac12\int_{M\cap\{ r\geq\delta\}}\left|\nabla_g\left(\eta_\delta (4\log r-2\log (\epsilon+r_\epsilon^2))\right)\right|^2dv_g.
