\label{lem:bubble-neck-integral}
		As $\epsilon\to0$, we have
		\begin{equation}\label{eq:bubble-neck-integral}
			\int_{M}
			\phi_{\epsilon,\delta}\,dv_g
			=|M|\log\epsilon+O(\delta\sqrt{\epsilon})+o(\sqrt{\epsilon}).
		\end{equation}

Firstly, noting that $$|\phi_{\epsilon,\delta}|\leq -2\log (\epsilon+ r_\epsilon^2)+\log\epsilon+C,\ \ for\ \ r_\epsilon\leq 2\alpha\sqrt{\epsilon},$$
		we have
		\begin{align*}
			\int_{M\cap\{r_\epsilon<2R_\epsilon\}}
			|\phi_{\epsilon,\delta}|\,dv_g &\leq \int_{\{r_\epsilon<2R_\epsilon,\ x_2\geq 0\}}
			(-2\log (\epsilon+ r_\epsilon^2)+\log\epsilon+C)\,dx +o(\sqrt\epsilon)\\
			&=-\pi\epsilon\left( 4\alpha^2\log\epsilon+(1+4\alpha^2)\log(1+4\alpha^2)-4\alpha^2\right)+2\pi\alpha^2\epsilon\log\epsilon +C\alpha^2\epsilon+o(\sqrt\epsilon) \\
			&=-4\pi \alpha^2\epsilon\log (\alpha^2\epsilon)+2\pi\alpha^2\epsilon\log\epsilon+o(\sqrt{\epsilon})\\
			&=-4\pi \alpha^2\epsilon\log (\alpha^2\sqrt{\epsilon})+o(\sqrt{\epsilon})=o(\sqrt{\epsilon}).
		\end{align*}

		Secondly,
		\begin{align*}
			\int_{M\cap\{r_\epsilon\geq 2R_\epsilon\}}
			\phi_{\epsilon,\delta}\,dv_g &=|M|\log\epsilon-\int_{M\cap\{r_\epsilon\leq 2R_\epsilon\}}
			(G+\log\epsilon)\,dv_g +\int_{M\cap\{r_\epsilon\geq 2R_\epsilon\}}
			\eta_\delta(4\log r-2\log(\epsilon+r_\epsilon^2))\,dv_g \\
			&=|M|\log\epsilon-\int_{M\cap\{r_\epsilon\leq 2R_\epsilon\}}
			(G+\log\epsilon+4\log r-2\log(\epsilon+r_\epsilon^2))\,dv_g \\&\quad +\int_{M\cap\{r\leq 2\delta\}}
			\eta_\delta(4\log r-2\log(\epsilon+r_\epsilon^2))\,dv_g\\
			&=|M|\log\epsilon +\int_{M\cap\{r\leq 2\delta\}}
			\eta_\delta(4\log r-2\log(\epsilon+r_\epsilon^2))\,dv_g+o(\sqrt{\epsilon})\\
			&=|M|\log\epsilon +\int_{M\cap\{100\sqrt\epsilon\leq r\leq 2\delta\}}
			\eta_\delta(4\log r-2\log(\epsilon+r_\epsilon^2))\,dv_g+o(\sqrt{\epsilon}),
		\end{align*} where the last equality follows from the fact that $$\int_{M\cap\{ r\leq 100\sqrt\epsilon\}}
		\eta_\delta(4\log r-2\log(\epsilon+r_\epsilon^2))\,dv_g=O(\epsilon\log\epsilon)=o(\sqrt{\epsilon}).$$

		Noting that
		\begin{align*}
			|4\log r-2\log(\epsilon+r_\epsilon^2)|&=2\log\left(1+\frac{2a\sqrt{\epsilon}x_2+(a^2+1)\epsilon}{r^2}\right)\\
			&\leq 2\frac{2a\sqrt{\epsilon}x_2+(a^2+1)\epsilon}{r^2},
		\end{align*} for $ x_2\geq 0$, we get
		\begin{align*}
			\int_{M\cap\{100\sqrt\epsilon\leq r\leq 2\delta\}}
			|4\log r-2\log(\epsilon+r_\epsilon^2)|\,dv_g&\leq C\int_{M\cap\{100\sqrt\epsilon\leq r\leq 2\delta\}}(\frac{\sqrt{\epsilon}}{r}+\frac{\epsilon}{r^2})dv_g\\ &=O(\delta\sqrt{\epsilon})+o(\sqrt{\epsilon}).
		\end{align*}

\noindent\textbf{Step 1:} Compute $\int_{M\cap \{r_\epsilon\leq R_\epsilon\}}K(x)e^{\phi_{\epsilon,\delta}}\,dv_g$.

		\

		Since
		\begin{align}\label{equation:12}
			K(x)e^{\phi_{\epsilon,\delta}}&=\epsilon K(p)e^{A(p)}\frac{1}{(\epsilon+r_\epsilon^2)^2}e^{(b_1+\frac{K_1(p)}{K(p)})x_1+ (b_2+\frac{K_2(p)}{K(p)})x_2+O(r^2)}\notag\\
			&=\epsilon K(p)e^{A(p)}\frac{1+(b_1+\frac{K_1(p)}{K(p)})x_1+ (b_2+\frac{K_2(p)}{K(p)})x_2}{(\epsilon+r_\epsilon^2)^2}+O(1)
		\end{align} and
		\begin{align*}
			\int_{\{r_\epsilon\leq R_\epsilon,\ 0\leq x_2\leq f(x_1)\}}\frac{1}{r_\epsilon}dv_g&\leq C\int_0^{R_\epsilon}\int_0^{f(x_1)} \frac{1}{r_\epsilon}dv_g=O(R_\epsilon^2),
		\end{align*}
		we have
		\begin{align*}
			&\int_{M\cap \{r_\epsilon\leq R_\epsilon\}}K(x)e^{\phi_{\epsilon,\delta}}\,dv_g \\&= \epsilon K(p)e^{A(p)} \int_{M\cap \{r_\epsilon\leq R_\epsilon\}}\frac{1+(b_1+\frac{K_1(p)}{K(p)})x_1+ (b_2+\frac{K_2(p)}{K(p)})x_2}{(\epsilon+r_\epsilon^2)^2}dx+O(R_\epsilon^2)\\
			&=  \epsilon K(p)e^{A(p)} \left(\int_{ \{r_\epsilon\leq R_\epsilon,\ x_2\geq 0\}}\frac{(b_1+\frac{K_1(p)}{K(p)})x_1+ (b_2+\frac{K_2(p)}{K(p)})x_2}{(\epsilon+r_\epsilon^2)^2}dx +\int_{ M\cap \{r_\epsilon\leq R_\epsilon\}} \frac{1}{(\epsilon+r_\epsilon^2)^2}dx\right)+o(\sqrt{\epsilon})\\
			&=  \epsilon K(p)e^{A(p)} \left(\int_{ \{r_\epsilon\leq R_\epsilon,\ x_2\geq 0\}}\frac{ (b_2+\frac{K_2(p)}{K(p)})x_2}{(\epsilon+r_\epsilon^2)^2}dx + \int_{ M\cap \{r_\epsilon\leq R_\epsilon\}} \frac{1}{(\epsilon+r_\epsilon^2)^2}dx\right)+o(\sqrt{\epsilon}).
		\end{align*}
		Set $x_1=\sqrt{\epsilon}y_1$, $x_2+a\sqrt{\epsilon}=\sqrt{\epsilon}y_2$. On one hand, by \eqref{equation:07}, we have
		\begin{align}\label{equation:13}
			\int_{|y|\leq \alpha,\ y_2\geq a}\frac{1}{(1+|y|^2)^2}dy
			&=\int_{|y|\leq \alpha,\ y_2\geq 0}\frac{1}{(1+|y|^2)^2}dy -\int_{|y|\leq \alpha,\ 0\leq y_2\leq a}\frac{1}{(1+|y|^2)^2}dy\notag \\
			&=\frac{\pi}{2}\frac{\alpha^2}{\alpha^2+1}-\frac{\pi}{2}\frac{a}{\sqrt{a^2+1}}+O(\frac{1}{\alpha^3})\notag\\&= \frac{\pi}{2}\left(1-\frac{a}{\sqrt{a^2+1}}\right)-\frac{\pi}{2\alpha^2}+o(\sqrt{\epsilon}).
		\end{align}
		Noting that
		\begin{align*}
			\int_{|y|\leq \alpha,\ a\leq y_2\leq a+d_\epsilon(y_1)}\frac{1}{(1+|y|^2)^2}dy
			&=\int_{|y|\leq \alpha,\ a\leq y_2\leq a+d_\epsilon(y_1)}\frac{1}{(1+a^2+y_1^2)^2}dy+o(\sqrt{\epsilon})\\
			&=2\int_0^{\sqrt{\alpha^2-a^2}}\frac{\frac{1}{2}\kappa \sqrt{\epsilon}y_1^2+O(\epsilon y_1^3)}{(1+a^2+y_1^2)^2}dy_1+o(\sqrt{\epsilon})\\
			&=\frac{\pi}{4}\frac{1}{\sqrt{a^2+1}}\kappa\sqrt{\epsilon}+o(\sqrt{\epsilon}),
		\end{align*}
		then
		\begin{align*}
			\epsilon\int_{ M\cap \{r_\epsilon\leq R_\epsilon\}}\frac{ 1}{(\epsilon+r_\epsilon^2)^2}dx &=\int_{|y|\leq \alpha,\ y_2\geq a}\frac{1}{(1+|y|^2)^2}dy-\int_{|y|\leq \alpha,\ a\leq y_2\leq a+d_\epsilon(y_1)}\frac{1}{(1+|y|^2)^2}dy \\
			&=\frac{\pi}{2}\left(1-\frac{a}{\sqrt{a^2+1}}\right)-\frac{\pi}{2\alpha^2}-\frac{\pi}{4}\frac{1}{\sqrt{a^2+1}}\kappa\sqrt{\epsilon}+o(\sqrt{\epsilon}).
		\end{align*}


		On the other hand, there holds
		\begin{align*}
			\epsilon\int_{  \{r_\epsilon\leq R_\epsilon,\ x_2\geq 0\}}\frac{ x_2}{(\epsilon+r_\epsilon^2)^2}dx&=\sqrt{\epsilon}\int_{|y|\leq \alpha,\ y_2\geq a}\frac{y_2-a}{(1+|y|^2)^2}dy\\
			&=\sqrt{\epsilon}\int_{|y|\leq \alpha,\ y_2\geq a}\frac{y_2}{(1+|y|^2)^2}dy-a\sqrt{\epsilon}\frac{\pi}{2}\left(1-\frac{a}{\sqrt{a^2+1}}\right)+o(\sqrt{\epsilon}).
		\end{align*}

		A direct computation yields
		\begin{align*}
			\int_{|y|\leq \alpha,\ y_2\geq a}\frac{y_2}{(1+|y|^2)^2}dy&=\int_{|y|\leq \alpha,\ y_2\geq 0}\frac{y_2}{(1+|y|^2)^2}dy -\int_{|y|\leq \alpha,\ 0\leq y_2\leq a}\frac{y_2}{(1+|y|^2)^2}dy
			\\&=\arctan\alpha-\frac{\alpha}{\alpha^2+1}-\int_{|y_1|\leq \alpha,\ 0\leq y_2\leq a}\frac{y_2}{(1+|y|^2)^2}dy+O(\alpha^{-3})\\
			&=-\frac{\alpha}{\alpha^2+1}+\frac{1}{\sqrt{1+a^2}}\arctan\frac{\alpha}{\sqrt{1+a^2}}+O(\alpha^{-3})\\
			&=\frac{\pi}{2}\frac{1}{\sqrt{1+a^2}}+O(\alpha^{-1}).
		\end{align*}

		Then
		\begin{align*}
			\epsilon\int_{  \{r_\epsilon\leq R_\epsilon,\ x_2\geq 0\}}\frac{ x_2}{(\epsilon+r_\epsilon^2)^2}dx=\frac{\pi \sqrt{\epsilon}}{2}(\sqrt{a^2+1}-a)+o(\sqrt{\epsilon}).
		\end{align*}



		Thus,
		\begin{align}
			\int_{M\cap\{r_\epsilon\leq R_\epsilon\}}
			K(x)e^{\phi_{\epsilon,\delta}}\,dv_g &=
			K(p)e^{A(p)}
			\Bigg\{
			\frac{\pi}{2}
			\left(
			1-\frac{a}{\sqrt{1+a^2}}
			\right)
			-\frac{\pi}{2\alpha^2} \notag\\
			&\quad+
			\frac{\pi}{2}
			\left[
			\bigl(\sqrt{1+a^2}-a\bigr)
			\left(
			\frac{K_2(p)}{K(p)}+b_2(p)
			\right)
			-\frac{\kappa(p)}{2\sqrt{1+a^2}}
			\right]\sqrt{\epsilon}
			+o(\sqrt{\epsilon})
			\Bigg\}.
		\end{align}

		\

		\noindent\textbf{Step 2:} Compute $\int_{M\cap\{R_\epsilon\leq r_\epsilon\leq 2R_\epsilon\}}
		K(x)e^{\phi_{\epsilon,\delta}}\,dv_g$.

		\

		Since for $R_\epsilon\leq r_\epsilon\leq 2R_\epsilon$, we have
		\begin{equation}\label{equation:14}
			\phi_{\epsilon,\delta}
			=
			-2\log\bigl(\epsilon+r_\epsilon^2\bigr)
			+A(p)+b_1(p)x_1+b_2(p)x_2
			+\log\epsilon+O(R_\epsilon^2).
		\end{equation}
		Then by Step 1 of this lemma, we get
		\begin{align*}
			\int_{M\cap\{R_\epsilon\leq r_\epsilon\leq 2R_\epsilon\}}
			K(x)e^{\phi_{\epsilon,\delta}}\,dv_g&=\int_{M\cap\{R_\epsilon\leq r_\epsilon\leq 2R_\epsilon\}}
			K(x)e^{-2\log(\epsilon+r_\epsilon^2)
				+A(p)+b_1(p)x_1+b_2(p)x_2
				+\log\epsilon}\,dv_g+O(R_\epsilon^2)\\
			&=K(p)e^{A(p)}(-\frac{\pi}{2})(\frac{1}{4\alpha^2}-\frac{1}{\alpha^2})+o(\sqrt{\epsilon})\\
			&=K(p)e^{A(p)}\frac{3\pi}{8\alpha^2}+o(\sqrt{\epsilon}).
		\end{align*}

		\

		\noindent\textbf{Step 3:} Compute $\int_{M\cap\{ r_\epsilon\geq 2R_\epsilon\}}
		K(x)e^{\phi_{\epsilon,\delta}}\,dv_g$.

		\

		On one hand, it is easy to see that
		\begin{align*}
			\left|\int_{M\cap\{ r\geq \delta\}}
			K(x)e^{\phi_{\epsilon,\delta}}\,dv_g\right|&\leq C(\delta)\epsilon=o(\sqrt{\epsilon}).
		\end{align*}

		On the other hand, noting that for $ r\leq \delta$, there holds $$
		\phi_{\epsilon,\delta}
		=
		-2\log\bigl(\epsilon+r_\epsilon^2\bigr)
		+A(p)+b_1(p)x_1+b_2(p)x_2
		+\log\epsilon+O(r^2).
		$$
		Then
		\begin{align*}
			\int_{M\cap\{r_\epsilon\geq 2R_\epsilon, \ r\leq \delta\}}
			K(x)e^{\phi_{\epsilon,\delta}}\,dv_g&=\epsilon K(p)e^{A(p)}\int_{M\cap\{r_\epsilon\geq 2R_\epsilon, \ r\leq \delta\}}\frac{1+O(r)}{(\epsilon+r_\epsilon^2)^2}dx+o(\sqrt{\epsilon})\\
			&=\epsilon K(p)e^{A(p)}\int_{M\cap\{r_\epsilon\geq 2R_\epsilon, \ r\leq \delta\}}\frac{1}{(\epsilon+r_\epsilon^2)^2}dx+o(\sqrt{\epsilon})\\
			&=\epsilon K(p)e^{A(p)}\int_{M\cap\{r_\epsilon\geq 2R_\epsilon \}}\frac{1}{(\epsilon+r_\epsilon^2)^2}dx+o(\sqrt{\epsilon})\\
			&=\epsilon K(p)e^{A(p)}\int_{\{r_\epsilon\geq 2R_\epsilon,\ x_2\geq 0\}}\frac{1}{(\epsilon+r_\epsilon^2)^2}dx+o(\sqrt{\epsilon}).
		\end{align*}
		where we used the fact that
		\begin{align*}
			\epsilon \int_{\{r_\epsilon\geq 2R_\epsilon, \ 0\leq x_2\leq f(x_1)\}}\frac{1}{(\epsilon+r_\epsilon^2)^2}dx&\leq \epsilon \int_{\{R_\epsilon\leq r,\ 0\leq x_2\leq f(x_1)\}}\frac{1}{(\epsilon+r_\epsilon^2)^2}dx =o(\sqrt{\epsilon}).
		\end{align*}
		By \eqref{equation:13}, we get
		\begin{align*}
			\epsilon K(p)e^{A(p)}\int_{\{r_\epsilon\geq 2R_\epsilon,\ x_2\geq 0\}}\frac{1}{(\epsilon+r_\epsilon^2)^2}dx& = K(p)e^{A(p)}\int_{|y|\geq 2\alpha,\ y_2\geq a}\frac{1}{(1+|y|^2)^2}dy\\
			&=K(p)e^{A(p)} \frac{\pi}{8\alpha^2}+o(\sqrt{\epsilon}).
		\end{align*}

		Then
		\begin{align*}
			\int_MK(x)e^{\phi_{\epsilon,\delta}}\,dv_g
			&=
			\frac{\pi}{2}K(p)e^{A(p)}
			\left(
			1-\frac{a}{\sqrt{1+a^2}}
			\right) \notag\\
			&\quad
			+
			\frac{\pi}{2}K(p)e^{A(p)}
			\left[
			\bigl(\sqrt{1+a^2}-a\bigr)
			\left(
			\frac{K_2(p)}{K(p)}+b_2(p)
			\right)
			-
			\frac{\kappa(p)}{2\sqrt{1+a^2}}
			\right]\sqrt{\epsilon}
			+
			o(\sqrt{\epsilon})
			.
		\end{align*}

\label{lem:bubble-boundary-exponential-integral}
		As $\epsilon\to0$, we have
		\begin{align*}
			&\log
			\int_{\partial M}
			h(x)e^{\phi_{\epsilon,\delta}/2}\,ds_g \\
			&=
			\frac{A(p)}{2}
			+
			\log h(p)
			+
			\log\frac{\pi}{\sqrt{1+a^2}} \notag\\
			&\quad
			+
			\Bigg[
			-\frac{a\kappa(p)}{2}
			+
			\frac{\sqrt{1+a^2}}
			{\pi e^{A(p)/2}h(p)}
			\left(
			\int_{\partial M\cap\{r\geq\delta\}}
			h(x)e^{G(x,p)/2}\,ds_g
			-
			\frac{2e^{A(p)/2}h(p)}{\delta}
			\right)
			\Bigg]\sqrt{\epsilon} \notag\\
			&\quad
			+
			O(\delta\sqrt{\epsilon})
			+
			o(\sqrt{\epsilon}).
		\end{align*}

\noindent\textbf{Step 1:} Compute $\int_{\partial M\cap\{r_\epsilon\leq R_\epsilon\}}
		h(x)e^{\phi_{\epsilon,\delta}/2}\,ds_g$.

		\

		Since
		\begin{align*}
			h(x)e^{\frac{1}{2}\phi_{\epsilon,\delta}}&=\sqrt{\epsilon} h(p)e^{\frac{1}{2}A(p)}\frac{1+(\frac{1}{2}b_1+\frac{h_1(p)}{h(p)})x_1+ O(x^2_1)}{\epsilon+r_\epsilon^2},\ \ x\in \partial M\cap\{r_\epsilon\leq R_\epsilon\}
		\end{align*} and
		\begin{align*}
			ds_g=\left|\frac{\partial}{\partial x_1}+f'(x_1)\frac{\partial}{\partial x_2}\right|_gdx_1=(1+O(x_1^2))dx_1,
		\end{align*}
		we have
		\begin{align*}
			&\int_{\partial M\cap\{r_\epsilon\leq R_\epsilon\}}
			h(x)e^{\phi_{\epsilon,\delta}/2}\,ds_g = \sqrt{\epsilon} h(p)e^{\frac{1}{2}A(p)}\int_{\partial M\cap\{r_\epsilon\leq R_\epsilon\}}\frac{1+(\frac{1}{2}b_1+\frac{h_1(p)}{h(p)})x_1}{\epsilon+r_\epsilon^2}dx_1+o(\sqrt{\epsilon}).
		\end{align*}

		Let $(l_\epsilon^+,f(l_\epsilon^+))$, $(l_\epsilon^-,f(l_\epsilon^-))$ be the two endpoints of
		$\partial M\cap\{r_\epsilon= R_\epsilon\}$ where $l_\epsilon^-<0<l_\epsilon^+$. Then
		$$
		(l_\epsilon^\pm)^2
		+
		\bigl(f(l_\epsilon^\pm)+a\sqrt{\epsilon}\bigr)^2
		=
		\alpha^2\epsilon,
		$$ which implies that $$\sqrt{\alpha^2-a^2}\sqrt{\epsilon}-|l_\epsilon^{\pm}|=\frac{1}{2}a\kappa \sqrt{\alpha^2-a^2}\epsilon+O((\alpha\sqrt{\epsilon})^3).$$

		Since
		\begin{align*}
			\sqrt{\epsilon}\left|\int_{\partial M\cap\{r_\epsilon\leq R_\epsilon\}}\left(\frac{x_1}{\epsilon+r_\epsilon^2}- \frac{x_1}{\epsilon+x_1^2+(\frac{1}{2}\kappa x_1^2)^2+a^2\epsilon}\right)dx_1\right| &\leq C\sqrt{\epsilon} \int_{\partial M\cap\{r_\epsilon\leq R_\epsilon\}}\frac{x_1^6+\sqrt{\epsilon}|x_1^3|}{(\epsilon+x_1^2)^2}dx_1\\&=o(\sqrt{\epsilon})
		\end{align*} and
		\begin{align*}
			\sqrt{\epsilon}\int_{\partial M\cap\{r_\epsilon\leq R_\epsilon\}} \frac{x_1}{\epsilon+x_1^2+(\frac{1}{2}\kappa x_1^2)^2+a^2\epsilon}dx_1 &=\sqrt{\epsilon}\int_{l^-_\epsilon}^{l^+_\epsilon} \frac{x_1}{\epsilon+x_1^2+(\frac{1}{2}\kappa x_1^2)^2+a^2\epsilon}dx_1=o(\sqrt{\epsilon}),
		\end{align*}where we used the symmetric property of the integration, thus we get
		\begin{align*}
			\int_{\partial M\cap\{r_\epsilon\leq R_\epsilon\}}
			h(x)e^{\phi_{\epsilon,\delta}/2}\,ds_g &= \sqrt{\epsilon} h(p)e^{\frac{1}{2}A(p)}\int_{\partial M\cap\{r_\epsilon\leq R_\epsilon\}}\frac{1}{\epsilon+r_\epsilon^2}dx_1+o(\sqrt{\epsilon})\\
			&= \sqrt{\epsilon} h(p)e^{\frac{1}{2}A(p)}\int_{\partial M\cap\{|x_1|\leq \sqrt{\alpha^2-a^2}\sqrt{\epsilon}\}}\frac{1}{\epsilon+r_\epsilon^2}dx_1+o(\sqrt{\epsilon})
		\end{align*} where the last equality follows from
		\begin{align*}
			\sqrt{\epsilon}\int_{\partial M\cap\{|x_1|\leq \sqrt{\alpha^2-a^2}\sqrt{\epsilon},\ r_\epsilon\geq R_\epsilon\}}\frac{1}{\epsilon+r_\epsilon^2}dx_1\leq C\frac{\sqrt{\epsilon}}{R_\epsilon^2}(\sqrt{\alpha^2-a^2}\sqrt{\epsilon}-|l_\epsilon^{\pm}|)=O(\sqrt{\epsilon}\alpha^{-1})=o(\sqrt{\epsilon})
		\end{align*}

		Set $x_1=\sqrt{\epsilon}t$, then
		\begin{align*}
			&\sqrt{\epsilon} \int_{\partial M\cap\{|x_1|\leq \sqrt{\alpha^2-a^2}\sqrt{\epsilon}\}}\frac{1}{\epsilon+r_\epsilon^2}dx_1\\
			&=\int_{|t|\leq \sqrt{\alpha^2-a^2}}\frac{1}{a^2+1+t^2+a\kappa \sqrt{\epsilon}t^2+\epsilon\cdot (O(t^3)+O(t^4))}dt\\
			&=\int_{|t|\leq \sqrt{\alpha^2-a^2}}\left[\frac{1}{1+a^2+t^2}
			-
			a\kappa\sqrt{\epsilon}
			\frac{t^2}{(1+a^2+t^2)^2}+
			O\left(
			\epsilon\frac{|t|^3+|t|^4}{(1+a^2+t^2)^2}
			+
			\epsilon\frac{t^4}{(1+a^2+t^2)^3}
			\right)\right]dt\\
			&=\frac{2}{\sqrt{1+a^2}}\arctan \frac{\sqrt{\alpha^2-a^2}}{\sqrt{1+a^2}}-\frac{a\kappa}{\sqrt{1+a^2}}\arctan \frac{\sqrt{\alpha^2-a^2}}{\sqrt{1+a^2}}\sqrt{\epsilon}+o(\sqrt{\epsilon})\\
			&=\frac{\pi}{\sqrt{1+a^2}}
			-\frac{2}{\alpha}
			-\frac{\pi a\kappa}{2\sqrt{1+a^2}}
			\sqrt{\epsilon}+o(\sqrt{\epsilon}).
		\end{align*}
		Then
		\begin{align*}
			&\int_{\partial M\cap\{r_\epsilon\leq R_\epsilon\}}
			h(x)e^{\phi_{\epsilon,\delta}/2}\,ds_g =
			e^{A(p)/2}h(p)
			\left[
			\frac{\pi}{\sqrt{1+a^2}}
			-\frac{2}{\alpha}
			-\frac{\pi a\kappa(p)}{2\sqrt{1+a^2}}
			\sqrt{\epsilon}
			+
			o(\sqrt{\epsilon})
			\right].
		\end{align*}

		\

		\noindent\textbf{Step 2:} Compute $\int_{\partial M\cap\{R_\epsilon\leq r_\epsilon\leq 2R_\epsilon\}}
		h(x)e^{\phi_{\epsilon,\delta}/2}\,ds_g$.

		\

		By \eqref{equation:14} and Step 1, we get
		$$\int_{\partial M\cap\{R_\epsilon\leq r_\epsilon\leq 2R_\epsilon\}}
		h(x)e^{\phi_{\epsilon,\delta}/2}\,ds_g=e^{A(p)/2}h(p)\frac{1}{\alpha}+o(\sqrt{\epsilon}).$$


		\

		\noindent\textbf{Step 3:} Compute $\int_{\partial M\cap\{ r_\epsilon\geq 2R_\epsilon\}}
		h(x)e^{\phi_{\epsilon,\delta}/2}\,ds_g$.

		\

		On one hand, noting that
		\begin{align*}
			\int_{\partial M\cap\{ \delta\leq r\leq 2\delta\}}
			h(x)e^{\phi_{\epsilon,\delta}/2}\,ds_g&=\sqrt{\epsilon}\int_{\partial M\cap\{ \delta\leq r\leq 2\delta\}}h(x)e^{\frac{1}{2}G}\left(1+O(\frac{\sqrt{\epsilon}}{\delta})+o(\sqrt{\epsilon})\right)ds_g\\
			&=\sqrt{\epsilon}\int_{\partial M\cap\{\delta\leq r\leq 2\delta\}}h(x)e^{\frac{1}{2}G}ds_g+o(\sqrt{\epsilon}),
		\end{align*}
		we have
		\begin{align*}
			\int_{\partial M\cap\{ r\geq\delta\}}
			h(x)e^{\phi_{\epsilon,\delta}/2}\,ds_g&=\sqrt{\epsilon}\int_{\partial M\cap\{ r\geq \delta\}}h(x)e^{\frac{1}{2}G}ds_g+o(\sqrt{\epsilon}).
		\end{align*}

		On the other hand, we get
		\begin{align*}
			&\int_{\partial M\cap\{ r_\epsilon\geq 2R_\epsilon,\  r\leq \delta\}}
			h(x)e^{\phi_{\epsilon,\delta}/2}\,ds_g\\
			&=\sqrt{\epsilon} h(p)e^{\frac{1}{2}A(p)}\int_{\partial M\cap\{r_\epsilon\geq 2R_\epsilon,\  r\leq \delta\}}\frac{1+(\frac{1}{2}b_1+\frac{h_1(p)}{h(p)})x_1+O(x_1^2)}{\epsilon+r_\epsilon^2}(1+O(x_1^2))dx_1\\
			&=\sqrt{\epsilon} h(p)e^{\frac{1}{2}A(p)}\int_{\partial M\cap\{r_\epsilon\geq 2R_\epsilon,\  r\leq \delta\}}\frac{1+(\frac{1}{2}b_1+\frac{h_1(p)}{h(p)})x_1}{\epsilon+r_\epsilon^2}dx_1+O(\delta\sqrt{\epsilon}).
		\end{align*}

		Let $(j_\epsilon^+,f(j_\epsilon^+))$, $(j_\epsilon^-,f(j_\epsilon^-))$ be the two endpoints of
		$\partial M\cap\{r_\epsilon= 2R_\epsilon\}$ where $j_\epsilon^-<0<j_\epsilon^+$. Let $(j_\delta^+,f(j_\delta^+))$, $(j_\delta^-,f(j_\delta^-))$ be the two endpoints of
		$\partial M\cap\{r= \delta\}$ where $j_\delta^-<0<j_\delta^+$. Then
		$$
		(j_\epsilon^\pm)^2
		+
		\bigl(f(j_\epsilon^\pm)+a\sqrt{\epsilon}\bigr)^2
		=
		4R_\epsilon^2,\ \ (j_\delta^\pm)^2
		+
		\bigl(f(j_\delta^\pm)\bigr)^2
		=
		\delta^2,
		$$ which implies that $$\sqrt{4\alpha^2-a^2}\sqrt{\epsilon}-|j_\epsilon^{\pm}|=\frac{1}{2}a\kappa \sqrt{4\alpha^2-a^2}\epsilon+O((\alpha\sqrt{\epsilon})^3),\ \ \delta-|j_\delta^\pm|=O(\delta^3).$$

		Since
		\begin{align*}
			&\sqrt{\epsilon}\left|\int_{\partial M\cap\{r_\epsilon\geq 2R_\epsilon,\ r\leq\delta\}}\left(\frac{x_1}{\epsilon+r_\epsilon^2}- \frac{x_1}{\epsilon+x_1^2+(\frac{1}{2}\kappa x_1^2)^2+a^2\epsilon}\right)dx_1\right| \\
			&\leq C\sqrt{\epsilon} \int_{\partial M\cap\{r_\epsilon\geq 2R_\epsilon,\ r\leq\delta\}}\frac{x_1^6+\sqrt{\epsilon}|x_1^3|}{(\epsilon+x_1^2)^2}dx_1=O(\delta\sqrt{\epsilon})+o(\sqrt{\epsilon})
		\end{align*} and
		\begin{align*}
			&\sqrt{\epsilon}\left|\int_{\partial M\cap\{r_\epsilon\geq 2R_\epsilon,\ r\leq\delta\}} \frac{x_1}{\epsilon+x_1^2+(\frac{1}{2}\kappa x_1^2)^2+a^2\epsilon}dx_1 \right|\\
			&\leq \sqrt{\epsilon}\left(\left|\int_{|j^-_\epsilon|}^{j^+_\epsilon} \frac{x_1}{\epsilon+x_1^2+(\frac{1}{2}\kappa x_1^2)^2+a^2\epsilon}dx_1\right|+ \left|\int_{|j^-_\delta|}^{j^+_\delta} \frac{x_1}{\epsilon+x_1^2+(\frac{1}{2}\kappa x_1^2)^2+a^2\epsilon}dx_1\right|\right)\\
			&=O(\delta\sqrt{\epsilon})+o(\sqrt{\epsilon}),
		\end{align*}where we used the symmetric property of the integration to get the first inequality, thus we get
		\begin{align*}
			\int_{\partial M\cap\{ r_\epsilon\geq 2R_\epsilon,\  r\leq \delta\}}
			h(x)e^{\phi_{\epsilon,\delta}/2}\,ds_g=\sqrt{\epsilon} h(p)e^{\frac{1}{2}A(p)}\int_{\partial M\cap\{r_\epsilon\geq 2R_\epsilon,\  r\leq \delta\}}\frac{1}{\epsilon+r_\epsilon^2}dx_1+O(\delta\sqrt{\epsilon})+o(\sqrt{\epsilon}).
		\end{align*}

		Setting $x_1=\sqrt{\epsilon}t$, we have
		\begin{align*}
			\sqrt{\epsilon} \int_{\partial M\cap\{j^+_\epsilon\leq x_1\leq j_\delta^+\}}\frac{1}{\epsilon+r_\epsilon^2}dx_1 &=\int_{\frac{j^+_\epsilon}{\sqrt{\epsilon}}}^{\frac{j^+_\delta}{\sqrt{\epsilon}}}\frac{dt}{a^2+1+t^2 +a\kappa\sqrt{\epsilon}t^2+\epsilon O(t^4)}\\ &=\int_{\frac{j^+_\epsilon}{\sqrt{\epsilon}}}^{\frac{j^+_\delta}{\sqrt{\epsilon}}}\left(\frac{1}{a^2+1+t^2} -\frac{a\kappa \sqrt{\epsilon}t^2}{(a^2+1+t^2)^2}+ \frac{ \epsilon O(t^4)}{(a^2+1+t^2)^2}\right)dt\\
			&=\int_{\frac{j^+_\epsilon}{\sqrt{\epsilon}}}^{\frac{j^+_\delta}{\sqrt{\epsilon}}}\frac{1}{a^2+1+t^2}dt+O(\delta\sqrt{\epsilon})+o(\sqrt{\epsilon})\\
			&=\frac{1}{2\alpha}-\frac{\sqrt{\epsilon}}{\delta}+O(\delta\sqrt{\epsilon})+o(\sqrt{\epsilon}).
		\end{align*}
		Similarly,
		\begin{align*}
			\sqrt{\epsilon} \int_{\partial M\cap\{j^-_\delta\leq x_1\leq j_\epsilon^-\}}\frac{1}{\epsilon+r_\epsilon^2}dx_1 =\frac{1}{2\alpha}-\frac{\sqrt{\epsilon}}{\delta}+O(\delta\sqrt{\epsilon})+o(\sqrt{\epsilon}).
		\end{align*}
		Thus,
		\begin{align*}
			\int_{\partial M\cap\{ r_\epsilon\geq 2R_\epsilon,\  r\leq \delta\}}
			h(x)e^{\phi_{\epsilon,\delta}/2}\,ds_g= h(p)e^{\frac{1}{2}A(p)}\left(\frac{1}{\alpha}-\frac{2\sqrt{\epsilon}}{\delta}\right)+O(\delta\sqrt{\epsilon})+o(\sqrt{\epsilon})
		\end{align*} and
		\begin{align*}
			&\int_{\partial M\cap\{ r_\epsilon\geq 2R_\epsilon\}}
			h(x)e^{\phi_{\epsilon,\delta}/2}\,ds_g= h(p)e^{\frac{1}{2}A(p)}\left(\frac{1}{\alpha}-\frac{2\sqrt{\epsilon}}{\delta}\right)+\sqrt{\epsilon}\int_{\partial M\cap\{ r\geq \delta\}}h(x)e^{\frac{1}{2}G}ds_g+O(\delta\sqrt{\epsilon})+o(\sqrt{\epsilon}).
		\end{align*}

		Therefore,
		\begin{align*}
			&\int_{\partial M}
			h(x)e^{\phi_{\epsilon,\delta}/2}\,ds_g \\
			&=
			\frac{\pi e^{A(p)/2}h(p)}{\sqrt{1+a^2}}
			+
			\Bigg[
			\int_{\partial M\cap\{r\geq\delta\}}
			h(x)e^{G(x,p)/2}\,ds_g
			-
			\frac{2e^{A(p)/2}h(p)}{\delta}
			-
			\frac{\pi a\kappa(p)e^{A(p)/2}h(p)}
			{2\sqrt{1+a^2}}
			\Bigg]\sqrt{\epsilon}\\
			&\quad
			+
			O(\delta\sqrt{\epsilon})
			+
			o_\epsilon(\sqrt{\epsilon}).
		\end{align*}

\label{lem:boundary-green-finite-part}
		Let $p\in\partial M$, let $r=d_g(x,p)$, and assume that
		$h\in C^2(\partial M)$ and $h>0$. Then the limit
		\begin{equation}\label{eq:boundary-green-finite-part}
			\lim_{\delta\downarrow0}
			\left[
			\int_{\partial M\cap\{r\geq\delta\}}
			h(x)e^{G(x,p)/2}\,ds_g
			-
			\frac{2e^{A(p)/2}h(p)}{\delta}
			\right]
		\end{equation}
		exists and is finite.

We just need to show that the minimizer sequence $\{u_\epsilon\}$ given in Section \ref{sec:blow-up-analysis} does not blow up. Otherwise, on one hand, by Proposition \ref{prop:lower-bound}, we get
\begin{align*}
\inf_{u\in W^{1,2}(M)}J_{\rho,\rho'}(u)=\liminf_{\epsilon\to 0}J_{\rho_\epsilon,
			\rho'}(u_\epsilon)\geq& -4\pi+2\rho'+ 4\pi\log 4-2(2\pi+\rho')\log(2\pi+\rho')\notag\\&-2\pi \left(A(p) +\frac{\rho}{\pi}\log K(p)+\frac{\rho'}{\pi}\log h^2(p)\right).\end{align*}

On the other hand, by Proposition \ref{prop:01}, if we first take $\delta=\delta_0(M,\|K\|_{C^1(M)},\|h\|_{C^1(\partial M)})>0$ small, then for all $\epsilon$ sufficiently small, we have
\begin{align*}
J_{\rho,
			\rho'}(\phi_{\epsilon,\delta})<& -4\pi+2\rho'+ 4\pi\log 4-2(2\pi+\rho')\log(2\pi+\rho')\notag\\&-2\pi \left(A(p) +\frac{\rho}{\pi}\log K(p)+\frac{\rho'}{\pi}\log h^2(p)\right),\end{align*} which is a contradiction.
